module TopModule (
    input  logic clk,
    input  logic x,
    output logic z
);
    logic q1, q2, q3;
    logic d1, d2, d3;

    assign d1 = x ^ q1;
    assign d2 = x & ~q2;
    assign d3 = x | ~q3;

    always_ff @(posedge clk) begin
        q1 <= d1;
        q2 <= d2;
        q3 <= d3;
    end

    initial begin
        q1 = 1'b0;
        q2 = 1'b0;
        q3 = 1'b0;
    end

    assign z = ~(q1 | q2 | q3);

endmodule

