module tb_TopModule;
    logic clk;
    logic x;
    logic z;

    TopModule uut (
        .clk(clk),
        .x(x),
        .z(z)
    );

    // Clock generation
    initial clk = 0;
    always #5 clk = ~clk;

    // Behavioral model for expected output
    logic ref_q1 = 0, ref_q2 = 0, ref_q3 = 0;
    logic ref_z;
    assign ref_z = ~(ref_q1 | ref_q2 | ref_q3);

    always @(posedge clk) begin
        ref_q1 <= x ^ ref_q1;
        ref_q2 <= x & ~ref_q2;
        ref_q3 <= x | ~ref_q3;
    end

    initial begin
        x = 0;
        #2;
        // Check initial state
        if (z !== ref_z) begin
            $display("SELFTEST FAIL: Initial state mismatch. z=%b, expected=%b", z, ref_z);
            $finish;
        end

        // Apply test vectors
        // Test sequence: x = 0, 1, 1, 0, 1, 0, 0, 1
        @(posedge clk); #1; x = 0;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        @(posedge clk); #1; x = 1;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        @(posedge clk); #1; x = 1;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        @(posedge clk); #1; x = 0;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        @(posedge clk); #1; x = 1;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        @(posedge clk); #1; x = 0;
        @(posedge clk); #1;
        if (z !== ref_z) begin $display("SELFTEST FAIL at t=%0t: z=%b, expected=%b", $time, z, ref_z); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
